import re
def dependency_ready(items,completed):
 d={};key=re.compile(r'[a-z][a-z0-9]*(?:-[a-z0-9]+)*')
 for x in items:
  if not x or not all(key.fullmatch(y) for y in x) or x[0] in d:return None
  d[x[0]]=x[1:]
 if any(y not in d for v in d.values() for y in v):return None
 def cyc(n,s):
  if n in s:return True
  return any(cyc(x,s|{n}) for x in d[n])
 if any(cyc(x,set()) for x in d):return None
 c=set(completed);return sorted(x for x,v in d.items() if x not in c and all(y in c for y in v))
